    description TEXT NOT NULL DEFAULT '',
    hearing_grade VARCHAR(20) NOT NULL DEFAULT ''
        CHECK (hearing_grade IN ('normal', 'mild', 'moderate', 'moderately_severe', 'severe', 'profound', ''))
