COMMENT ON TABLE audiology_assessment.grading_fired_rule IS
    'Individual hearing level classification rules that evaluated to true during audiology grading.';
COMMENT ON COLUMN audiology_assessment.grading_fired_rule.grade_id IS
    'Foreign key to the parent grading result.';
COMMENT ON COLUMN audiology_assessment.grading_fired_rule.rule_id IS
